// Spiral Sunburst - color only, ANIMATED. Runs INSIDE shadeSurface().
// A turning spiral tunnel of light with a hot center, over a dark haze sprinkled
// with flashing sparkles. The vortex is painted by DIRECTION from the center of
// the scene: it is centered on the direction CENTER and fades out before the
// opposite side, so it never meets itself. Its arms use whole multiples of the
// angle, so they close around the center.
// No displacement: one evaluation per pixel, cheap at any resolution.
// In scope: pModel, t. Dock colors: u_col1 = light of the vortex, u_col2 = haze.

float ARMS   = floor(6.0 * max(E, 0.17) + 0.5);  // slider E   // spiral arms (whole)  [1 .. 12]
float SPIN   = 0.8 * F;                          // slider F   // rotation speed       [0 .. 3]
float TWIST  = 4.0;    // how tightly the arms wind                            [0 .. 10]
float REACH  = 1.9;    // angular size of the vortex (radians, < pi)           [0.5 .. 2.8]
vec3  CENTER = normalize(vec3(-0.5, 0.43, 0.75));  // where the vortex looks out (by
                                                  // default: toward the starting camera)

vec3 dir = normalize(pModel + vec3(1e-5));

// polar coordinates around CENTER: angular distance and angle around it
float ang = acos(clamp(dot(dir, CENTER), -1.0, 1.0));
vec3 tu = normalize(cross(CENTER, vec3(0.0, 1.0, 0.0)));
vec3 tv = cross(CENTER, tu);
float phi = atan(dot(dir, tv), dot(dir, tu));

// spiral arms: log-spiral phase, turning with time
float arm = 0.5 + 0.5 * cos(ARMS * phi + TWIST * log(ang + 0.03) - SPIN * t * 2.0);
arm = pow(arm, 3.0);
float fade = 1.0 - smoothstep(0.55 * REACH, REACH, ang);   // gone before the far side
float core = exp(-ang * 9.0);                               // the hot center
float rings = 0.5 + 0.5 * sin(30.0 * ang - 3.0 * SPIN * t);  // light rushing inward

// --- haze: a soft swirl of sines
vec3 q = dir * 3.0;
q += 0.6 * sin(q.yzx * 1.7 + 0.15 * t);
float haze = 0.5 + 0.5 * sin(q.x + q.y * 1.3 + q.z * 0.7);

// --- sparkles: one per cell on the direction, flashing briefly
vec3 sp = dir * 30.0;
vec3 ci = floor(sp);
vec3 h3 = fract(ci * vec3(0.1031, 0.1030, 0.0973));
h3 += dot(h3, h3.yxz + 33.33);
vec3 hr = fract((h3.xxy + h3.yxx) * h3.zyx);
vec3 rel = fract(sp) - (0.25 + 0.5 * hr);
float flash = pow(max(sin(t * (0.8 + 1.5 * hr.x) + 6.2832 * hr.y), 0.0), 12.0);
float sparkle = exp(-dot(rel, rel) / 0.004) * flash;

// --- composition
vec3 col = ubuf.u_col2 * (0.25 + 0.35 * haze);
vec3 light = mix(ubuf.u_col1, vec3(1.0, 0.95, 0.85), core);
col += light * (arm * (0.75 + 0.25 * rings) * 0.9 + core * 1.5) * fade;
col += vec3(1.0, 0.95, 0.85) * sparkle * (1.0 - 0.7 * fade * arm);

textureCol = col;
